int unique_paths_with_obstacles(vector<vector<int>> grid) {
    int cols = grid[0].size();
    vector<long long> row(cols, 0);
    row[0] = 1;
    for (const vector<int>& line : grid) {
        for (int c = 0; c < cols; ++c) {
            if (line[c] == 1) {
                row[c] = 0;
            } else if (c > 0) {
                row[c] += row[c - 1];
            }
        }
    }
    return (int)row[cols - 1];
}

